import type { TyposElement } from "../core/types.js";
import type { TyposEngine } from "../engine/TyposEngine.js";
import { getDirective } from "../core/element.js";
import { directiveKey } from "../core/registry.js";
import {
  COLOR_PROPERTIES,
  STYLE_ICONS,
  STYLE_PROPERTIES,
  STYLE_VALUES,
  type StyleIcon,
} from "../config/defaults.js";
import { h, makeDisposer, replaceChildren } from "./dom.js";

/**
 * Panneau d'inspection/édition de l'élément sélectionné.
 *
 * Chaque champ committe via updateElement avec sa coalesceKey — la
 * frappe reste fluide, l'historique reste propre (une entrée par champ
 * édité). Les propriétés de style ont : icônes raccourci en tête (ajout
 * instantané avec valeur par défaut), autocomplete propriétés + valeurs,
 * sélecteur de couleur natif pour les propriétés colorées.
 */
export class TyposStylePanel {
  private disposer = makeDisposer();
  private currentId: string | null = null;

  constructor(
    private container: HTMLElement,
    private engine: TyposEngine,
  ) {
    this.render();
    this.disposer.add(
      engine.on("selection:changed", ({ ids }) => {
        const next = ids[0] ?? null;
        if (next !== this.currentId) {
          this.currentId = next;
          this.render();
        }
      }),
    );
    this.disposer.add(
      engine.on("document:changed", () => {
        if (this.currentId && !this.el()) {
          this.currentId = null;
          this.render();
        }
      }),
    );
    this.disposer.add(engine.on("document:loaded", () => this.render()));
    this.disposer.add(engine.on("document:new", () => this.render()));
    this.disposer.add(engine.on("history:undo", () => this.render()));
    this.disposer.add(engine.on("history:redo", () => this.render()));

    this.ensureDatalists();
  }

  private el(): TyposElement | null {
    return this.currentId ? this.engine.findElement(this.currentId) : null;
  }

  private prefix(): string {
    return this.engine.document.settings.directivePrefix;
  }

  private patch(
    patch: Parameters<TyposEngine["updateElement"]>[1],
    field: string,
  ): void {
    if (!this.currentId) return;
    this.engine.updateElement(this.currentId, patch, {
      coalesceKey: `${field}:${this.currentId}`,
    });
  }

  /* ------------------------------------------------------------ UI - */

  private render(): void {
    const el = this.el();
    if (!el) {
      replaceChildren(
        this.container,
        h("div", { class: "typos-panel-title", text: "Élément" }),
        h("div", {
          class: "typos-empty",
          text: "Sélectionne un élément dans le canvas, l'arbre ou le graphe.",
        }),
      );
      return;
    }

    const isRoot = el.id === this.engine.tree.id;
    const locked = getDirective(el, "locked", this.prefix()) === true;
    const hidden = getDirective(el, "hidden", this.prefix()) === true;

    replaceChildren(
      this.container,
      h("div", { class: "typos-panel-title", text: "Élément" }),

      this.section(
        "Identité",
        this.fieldRow(
          "Nom",
          this.textInput(String(getDirective(el, "name", this.prefix()) ?? ""), (v) =>
            this.patch({ directives: { [directiveKey("name", this.prefix())]: v } }, "name"),
          ),
        ),
        this.fieldRow("Tag", this.tagInput(el)),
        this.metaRow("id", el.id),
        this.metaRow("path", String(getDirective(el, "path", this.prefix()) ?? "")),
        this.metaRow("kind", String(getDirective(el, "kind", this.prefix()) ?? "")),
      ),

      this.section(
        "Classes",
        this.textInput(el.classes.join(" "), (v) =>
          this.patch({ classes: v.split(/\s+/).filter(Boolean) }, "classes"),
        ),
      ),

      this.section("Attributs", this.kvEditor(el.attrs, false, (attrs) =>
        this.patch({ attrs }, "attrs"),
      )),

      this.styleSection(el),

      this.section(
        "CSS libre",
        this.textArea(
          el.customCss,
          (v) => this.patch({ customCss: v }, "css"),
          "sélecteurs complets, ou déclarations nues scopées par id",
        ),
      ),

      this.section(
        "Contenu (innerHtml)",
        el.children.length > 0
          ? h("div", { class: "typos-hint", text: "Enfants présents : le contenu est porté par l'arbre." })
          : this.textArea(el.innerHtml, (v) => this.patch({ innerHtml: v }, "html"), "HTML riche opaque"),
      ),

      this.section(
        "Script scopé",
        this.textArea(el.script, (v) => this.patch({ script: v }, "script"), "émis en <script data-…-script-for>"),
      ),

      this.section(
        "Éditeur",
        h(
          "div",
          { class: "typos-toggles" },
          this.toggle("Verrouillé", locked, (v) =>
            this.patch({ directives: { [directiveKey("locked", this.prefix())]: v } }, "locked"),
          ),
          this.toggle("Masqué", hidden, (v) =>
            this.patch({ directives: { [directiveKey("hidden", this.prefix())]: v } }, "hidden"),
          ),
        ),
      ),

      h(
        "div",
        { class: "typos-actions" },
        this.actionBtn("Cloner", !isRoot, () => {
          const id = this.engine.cloneElement(el.id);
          if (id) this.engine.select([id]);
        }),
        this.actionBtn("Envelopper", !isRoot, () => {
          const id = this.engine.wrapElement(el.id);
          if (id) this.engine.select([id]);
        }),
        this.actionBtn("Dissoudre", !isRoot && el.children.length > 0, () =>
          this.engine.unwrapElement(el.id),
        ),
        this.actionBtn("Supprimer", !isRoot, () => this.engine.removeElement(el.id), true),
      ),
    );
  }

  /* --------------------------------------------- section Style ----- */

  /**
   * En-tête d'icônes raccourci + éditeur clé/valeur avec autocomplete
   * et sélecteur de couleur pour les propriétés colorées.
   */
  private styleSection(el: TyposElement): HTMLElement {
    const shortcuts = h("div", { class: "typos-style-shortcuts" });
    for (const icon of STYLE_ICONS) {
      shortcuts.append(this.styleShortcutButton(icon, el));
    }
    return h(
      "section",
      { class: "typos-section" },
      h(
        "div",
        { class: "typos-section-head" },
        h("div", { class: "typos-section-title", text: "Style" }),
        shortcuts,
      ),
      this.kvEditor(el.styleOptions, true, (styleOptions) =>
        this.patch({ styleOptions }, "style"),
      ),
    );
  }

  private styleShortcutButton(icon: StyleIcon, el: TyposElement): HTMLElement {
    const already = icon.property in el.styleOptions;
    return h("button", {
      class: `typos-style-shortcut ${already ? "is-set" : ""}`,
      title: `${icon.label} — ${icon.property}`,
      text: icon.icon,
      style: {
        background: icon.tint,
        color: this.readableOn(icon.tint),
        borderColor: icon.tint,
      },
      on: {
        click: () => {
          const next = { ...el.styleOptions };
          if (!(icon.property in next)) next[icon.property] = icon.defaultValue;
          this.patch({ styleOptions: next }, `style-add:${icon.property}`);
          // Re-render synchrone : la nouvelle ligne KV doit être présente
          // dans le DOM immédiatement (l'utilisateur — ou un test — s'y
          // attend). Le focus, lui, attend la stabilisation du DOM.
          this.render();
          queueMicrotask(() => this.focusStyleField(icon.property));
        },
      },
    });
  }

  private focusStyleField(prop: string): void {
    const rows = this.container.querySelectorAll<HTMLInputElement>(
      `.typos-kv-row[data-key="${CSS.escape(prop)}"] input.typos-kv-val`,
    );
    rows[0]?.focus();
  }

  /* ------------------------------------------------------ widgets -- */

  private section(title: string, ...children: (HTMLElement | null)[]): HTMLElement {
    return h(
      "section",
      { class: "typos-section" },
      h("div", { class: "typos-section-title", text: title }),
      ...children,
    );
  }

  private fieldRow(label: string, input: HTMLElement): HTMLElement {
    return h(
      "label",
      { class: "typos-field" },
      h("span", { class: "typos-field-label", text: label }),
      input,
    );
  }

  private metaRow(label: string, value: string): HTMLElement {
    return h(
      "div",
      { class: "typos-meta" },
      h("span", { class: "typos-field-label", text: label }),
      h("code", { class: "typos-meta-value", text: value }),
    );
  }

  private textInput(value: string, commit: (v: string) => void): HTMLInputElement {
    return h("input", {
      class: "typos-input",
      attrs: { type: "text", value },
      on: { input: (e) => commit((e.target as HTMLInputElement).value) },
    });
  }

  /**
   * Éditeur clé/valeur générique. `withStyleAutocomplete=true` active :
   *  · datalist des propriétés CSS ;
   *  · datalist contextuel des valeurs (par propriété) ;
   *  · sélecteur de couleur natif pour les propriétés colorées.
   */
  private kvEditor(
    record: Record<string, string>,
    withStyleAutocomplete: boolean,
    commit: (next: Record<string, string>) => void,
  ): HTMLElement {
    const rows: Array<{ key: string; value: string }> = Object.entries(record).map(
      ([key, value]) => ({ key, value }),
    );
    const wrap = h("div", { class: "typos-kv" });

    const push = (): void => {
      const next: Record<string, string> = {};
      for (const row of rows) {
        const k = row.key.trim();
        if (k) next[k] = row.value;
      }
      commit(next);
    };

    const renderRows = (): void => {
      wrap.textContent = "";
      rows.forEach((row, i) => {
        const rowEl = h("div", {
          class: "typos-kv-row",
          attrs: { "data-key": row.key || `__${i}` },
        });
        const keyInput = h("input", {
          class: "typos-input typos-kv-key",
          attrs: {
            type: "text",
            value: row.key,
            placeholder: "propriété",
            list: withStyleAutocomplete ? "typos-css-props" : "",
          },
          on: {
            input: (e) => {
              row.key = (e.target as HTMLInputElement).value;
              rowEl.setAttribute("data-key", row.key || `__${i}`);
              this.retuneValueInput(rowEl, row.key, withStyleAutocomplete);
              push();
            },
          },
        });
        const valInput = h("input", {
          class: "typos-input typos-kv-val",
          attrs: { type: "text", value: row.value, placeholder: "valeur" },
          on: {
            input: (e) => {
              row.value = (e.target as HTMLInputElement).value;
              push();
            },
          },
        });
        rowEl.append(keyInput, valInput);
        if (withStyleAutocomplete) {
          this.tuneValueInput(rowEl, valInput, row.key, (v) => {
            row.value = v;
            valInput.value = v;
            push();
          });
        }
        rowEl.append(
          h("button", {
            class: "typos-btn typos-btn-icon",
            text: "×",
            title: "Retirer",
            on: {
              click: () => {
                rows.splice(i, 1);
                renderRows();
                push();
              },
            },
          }),
        );
        wrap.append(rowEl);
      });
      wrap.append(
        h("button", {
          class: "typos-btn typos-btn-icon",
          text: "+",
          title: "Ajouter",
          on: {
            click: () => {
              rows.push({ key: "", value: "" });
              renderRows();
            },
          },
        }),
      );
    };

    renderRows();
    return wrap;
  }

  /** Attache le datalist de valeurs et — si couleur — un input color natif. */
  private tuneValueInput(
    rowEl: HTMLElement,
    input: HTMLInputElement,
    key: string,
    commit: (v: string) => void,
  ): void {
    const listId = this.valueListIdFor(key);
    if (listId) input.setAttribute("list", listId);
    if (COLOR_PROPERTIES.has(key)) {
      const swatch = h("input", {
        class: "typos-color-swatch",
        attrs: { type: "color", value: toHexColor(input.value) },
        on: {
          input: (e) => commit((e.target as HTMLInputElement).value),
        },
      });
      rowEl.append(swatch);
    }
  }

  /** Réajuste le datalist / la présence du swatch quand la propriété change. */
  private retuneValueInput(
    rowEl: HTMLElement,
    key: string,
    withStyleAutocomplete: boolean,
  ): void {
    if (!withStyleAutocomplete) return;
    const valInput = rowEl.querySelector<HTMLInputElement>("input.typos-kv-val");
    if (!valInput) return;
    const listId = this.valueListIdFor(key);
    if (listId) valInput.setAttribute("list", listId);
    else valInput.removeAttribute("list");
    const existingSwatch = rowEl.querySelector(".typos-color-swatch");
    if (COLOR_PROPERTIES.has(key)) {
      if (!existingSwatch) {
        const swatch = h("input", {
          class: "typos-color-swatch",
          attrs: { type: "color", value: toHexColor(valInput.value) },
          on: {
            input: (e) => {
              valInput.value = (e.target as HTMLInputElement).value;
              valInput.dispatchEvent(new Event("input", { bubbles: true }));
            },
          },
        });
        rowEl.append(swatch);
      }
    } else if (existingSwatch) {
      existingSwatch.remove();
    }
  }

  private valueListIdFor(key: string): string | null {
    return STYLE_VALUES[key] ? `typos-css-values-${cssSafe(key)}` : null;
  }

  /** Datalists partagés — créés une fois, réutilisés par toutes les instances. */
  private ensureDatalists(): void {
    if (!document.getElementById("typos-css-props")) {
      const dl = h("datalist", { attrs: { id: "typos-css-props" } });
      for (const p of STYLE_PROPERTIES) dl.append(h("option", { attrs: { value: p } }));
      document.body.append(dl);
    }
    for (const [key, values] of Object.entries(STYLE_VALUES)) {
      const id = `typos-css-values-${cssSafe(key)}`;
      if (!document.getElementById(id)) {
        const dl = h("datalist", { attrs: { id } });
        for (const v of values) dl.append(h("option", { attrs: { value: v } }));
        document.body.append(dl);
      }
    }
  }

  private tagInput(el: TyposElement): HTMLElement {
    const list = "typos-tags-datalist";
    const wrap = h(
      "span",
      {},
      h("input", {
        class: "typos-input",
        attrs: { type: "text", value: el.type, list },
        on: {
          change: (e) => {
            const v = (e.target as HTMLInputElement).value.trim();
            if (/^[a-zA-Z][a-zA-Z0-9-]*$/.test(v)) this.patch({ type: v }, "type");
          },
        },
      }),
    );
    if (!document.getElementById(list)) {
      const dl = h("datalist", { attrs: { id: list } });
      for (const t of ["div", "section", "header", "footer", "nav", "main", "article", "aside", "h1", "h2", "h3", "p", "span", "a", "button", "img", "input", "ul", "ol", "li", "form", "label"]) {
        dl.append(h("option", { attrs: { value: t } }));
      }
      document.body.append(dl);
    }
    return wrap;
  }

  private textArea(value: string, commit: (v: string) => void, placeholder: string): HTMLTextAreaElement {
    const ta = h("textarea", {
      class: "typos-input typos-textarea",
      attrs: { rows: "4", placeholder, spellcheck: "false" },
      on: { input: (e) => commit((e.target as HTMLTextAreaElement).value) },
    });
    ta.value = value;
    return ta;
  }

  private toggle(label: string, value: boolean, commit: (v: boolean) => void): HTMLElement {
    const input = h("input", { attrs: { type: "checkbox" } });
    input.checked = value;
    input.addEventListener("change", () => commit(input.checked));
    return h("label", { class: "typos-toggle" }, input, h("span", { text: label }));
  }

  private actionBtn(label: string, enabled: boolean, fn: () => void, danger = false): HTMLButtonElement {
    const btn = h("button", {
      class: `typos-btn ${danger ? "typos-btn-danger" : ""}`,
      text: label,
      on: { click: fn },
    });
    btn.disabled = !enabled;
    return btn;
  }

  /** Choix noir/blanc contrasté sur un fond hex #RRGGBB. */
  private readableOn(hex: string): string {
    const m = /^#([0-9a-f]{6})$/i.exec(hex);
    if (!m) return "#1c1712";
    const n = parseInt(m[1]!, 16);
    const r = (n >> 16) & 0xff;
    const g = (n >> 8) & 0xff;
    const b = n & 0xff;
    // Luminance perceptuelle simplifiée.
    return r * 0.299 + g * 0.587 + b * 0.114 > 150 ? "#1c1712" : "#ffffff";
  }

  destroy(): void {
    this.disposer.flush();
    this.container.textContent = "";
  }
}

/** Chaîne sûre pour un id (datalist). */
function cssSafe(key: string): string {
  return key.replace(/[^a-z0-9-]/gi, "-");
}

/** Normalise une valeur en hex #RRGGBB pour l'input color. */
function toHexColor(value: string): string {
  const v = value.trim().toLowerCase();
  if (/^#[0-9a-f]{6}$/.test(v)) return v;
  if (/^#[0-9a-f]{3}$/.test(v)) {
    return `#${v[1]}${v[1]}${v[2]}${v[2]}${v[3]}${v[3]}`;
  }
  return "#000000";
}
