import type { TyposEngine } from "../engine/TyposEngine.js";
import { getParent } from "../core/tree.js";
import { OVERLAY_ICONS } from "../config/defaults.js";
import { h, makeDisposer } from "./dom.js";

type ResizeSide = "n" | "s" | "e" | "w" | "ne" | "nw" | "se" | "sw";

const RESIZE_THRESHOLD = 3;

/**
 * Overlay flottant sur l'élément sélectionné (icônes + poignées).
 *
 * Vit dans `.typos-overlay-layer` (couche épinglée au viewport du canvas,
 * fournie par TyposCanvas). Le rect reçu est déjà en coordonnées de cette
 * couche → un simple left/top/width/height suffit.
 *
 * RESIZE ROBUSTE (corrige le redimensionnement fantôme) :
 * ────────────────────────────────────────────────────────
 * Le geste utilise POINTER CAPTURE : au pointerdown sur une poignée, la
 * poignée capture le pointeur ; tous les pointermove/pointerup lui sont
 * envoyés jusqu'au relâchement, MÊME hors de la fenêtre. Le listener ne
 * peut donc jamais « rester attaché » et provoquer un resize au survol.
 * La taille de départ est figée au pointerdown. Sous 3px de mouvement,
 * rien ne change. `setRect` est gelé pendant le geste (isResizing).
 */
export class TyposSelectionOverlay {
  private disposer = makeDisposer();
  private root: HTMLElement;
  private bar!: HTMLElement;
  private handles: HTMLElement[] = [];
  private rect: DOMRect | null = null;
  private currentId: string | null = null;
  private isResizing = false;

  constructor(
    private container: HTMLElement,
    private engine: TyposEngine,
    private options: { onResizeEnd?: () => void } = {},
  ) {
    this.root = h("div", { class: "typos-overlay", attrs: { "aria-hidden": "true" } });
    this.buildBar();
    this.buildHandles();
    this.container.append(this.root);
    this.hide();

    this.disposer.add(
      engine.on("selection:changed", ({ ids }) => {
        this.currentId = ids[0] ?? null;
        if (!this.currentId) this.hide();
      }),
    );
  }

  setRect(rect: DOMRect | null): void {
    if (this.isResizing) return; // gèle le repositionnement pendant le geste
    this.rect = rect;
    if (!rect || !this.currentId) { this.hide(); return; }
    this.root.style.display = "block";
    this.root.style.left = `${rect.left}px`;
    this.root.style.top = `${rect.top}px`;
    this.root.style.width = `${rect.width}px`;
    this.root.style.height = `${rect.height}px`;
    this.bar.classList.toggle("is-below", rect.top < 40);
  }

  private hide(): void {
    this.root.style.display = "none";
  }

  /* ─────────────────────────── barre d'icônes ─────────────────────── */

  private buildBar(): void {
    this.bar = h("div", { class: "typos-overlay-bar" });
    for (const icon of OVERLAY_ICONS) {
      this.bar.append(h("button", {
        class: "typos-overlay-btn",
        title: icon.label,
        text: icon.icon,
        style: { color: icon.tint, borderColor: icon.tint },
        on: { click: (e) => { e.stopPropagation(); this.dispatch(icon.key); } },
      }));
    }
    this.bar.append(h("span", {
      class: "typos-overlay-grip",
      title: "Astuce : glisse l'élément directement dans le canvas pour le déplacer",
      text: "⋮⋮",
    }));
    this.root.append(this.bar);
  }

  private dispatch(key: (typeof OVERLAY_ICONS)[number]["key"]): void {
    if (!this.currentId) return;
    const id = this.currentId;
    const parent = getParent(this.engine.tree, id);
    switch (key) {
      case "delete":
        this.engine.removeElement(id);
        break;
      case "clone": {
        const cloneId = this.engine.cloneElement(id);
        if (cloneId) this.engine.select([cloneId]);
        break;
      }
      case "wrap": {
        const wrapId = this.engine.wrapElement(id);
        if (wrapId) this.engine.select([wrapId]);
        break;
      }
      case "up":
        if (parent) {
          const from = parent.children.findIndex((c) => c.id === id);
          if (from > 0) this.engine.reorderElement(id, from - 1);
        }
        break;
      case "down":
        if (parent) {
          const from = parent.children.findIndex((c) => c.id === id);
          if (from >= 0 && from < parent.children.length - 1) {
            this.engine.reorderElement(id, from + 1);
          }
        }
        break;
    }
  }

  /* ────────────────── poignées de resize (pointer capture) ───────── */

  private buildHandles(): void {
    const sides: ResizeSide[] = ["n", "s", "e", "w", "ne", "nw", "se", "sw"];
    for (const side of sides) {
      const handle = h("span", {
        class: `typos-overlay-handle handle-${side}`,
        attrs: { "data-side": side },
        on: {
          pointerdown: (e) => this.startResize(side, handle, e as PointerEvent),
          // Filet de sécurité si l'environnement n'a pas la capture.
          mousedown: (e) => { e.preventDefault(); e.stopPropagation(); },
        },
      });
      this.handles.push(handle);
      this.root.append(handle);
    }
  }

  private startResize(side: ResizeSide, handle: HTMLElement, downEvt: PointerEvent): void {
    if (!this.currentId || !this.rect) return;
    downEvt.preventDefault();
    downEvt.stopPropagation();

    const id = this.currentId;
    const el = this.engine.findElement(id);
    if (!el) return;

    // Taille et position de départ FIGÉES.
    const startW = this.rect.width;
    const startH = this.rect.height;
    const startLeft = this.rect.left;
    const startTop = this.rect.top;
    const startX = downEvt.clientX;
    const startY = downEvt.clientY;
    let started = false;

    this.isResizing = true;
    document.body.classList.add("typos-resizing");

    // POINTER CAPTURE : le geste est verrouillé sur la poignée.
    try { handle.setPointerCapture(downEvt.pointerId); } catch { /* ok */ }

    const move = (e: PointerEvent): void => {
      const dx = e.clientX - startX;
      const dy = e.clientY - startY;
      if (!started) {
        if (Math.abs(dx) < RESIZE_THRESHOLD && Math.abs(dy) < RESIZE_THRESHOLD) return;
        started = true;
      }
      let w = startW;
      let h2 = startH;
      if (side.includes("e")) w = startW + dx;
      if (side.includes("w")) w = startW - dx;
      if (side.includes("s")) h2 = startH + dy;
      if (side.includes("n")) h2 = startH - dy;
      w = Math.max(20, Math.round(w));
      h2 = Math.max(20, Math.round(h2));

      const current = this.engine.findElement(id);
      if (!current) return;
      const styleOptions: Record<string, string> = { ...current.styleOptions };
      if (side.includes("e") || side.includes("w")) styleOptions["width"] = `${w}px`;
      if (side.includes("n") || side.includes("s")) styleOptions["height"] = `${h2}px`;
      this.engine.updateElement(id, { styleOptions }, { coalesceKey: `resize:${id}` });

      // Suivi visuel de l'overlay (setRect est gelé pendant le geste).
      this.root.style.width = `${w}px`;
      this.root.style.height = `${h2}px`;
      if (side.includes("w")) this.root.style.left = `${startLeft + (startW - w)}px`;
      if (side.includes("n")) this.root.style.top = `${startTop + (startH - h2)}px`;
    };

    const end = (): void => {
      handle.removeEventListener("pointermove", move);
      handle.removeEventListener("pointerup", end);
      handle.removeEventListener("pointercancel", end);
      try { handle.releasePointerCapture(downEvt.pointerId); } catch { /* ok */ }
      document.body.classList.remove("typos-resizing");
      this.isResizing = false;
      // Recale l'overlay sur la géométrie RÉELLE de l'élément.
      this.options.onResizeEnd?.();
    };

    handle.addEventListener("pointermove", move);
    handle.addEventListener("pointerup", end);
    handle.addEventListener("pointercancel", end);
  }

  destroy(): void {
    this.disposer.flush();
    this.root.remove();
  }
}
