import type { DirectiveSpec, EmitProfile } from "./types.js";

/**
 * Registre exhaustif des directives Typos.
 *
 * Chaque élément de l'arbre porte un traçage JSON complet ; le HTML
 * généré n'estampille que ce que le profil d'émission autorise.
 *
 * Préfixe par défaut : "tekton" (compat moteur runtime KANTO APLO,
 * qui lit ces attributs comme Angular lit ses ng-* ou Alpine ses x-*).
 * Le préfixe est configurable document par document.
 */

export const DEFAULT_DIRECTIVE_PREFIX = "tekton";

/** Ordre des profils, pour comparer "à partir de quel profil on émet". */
const PROFILE_ORDER: Record<EmitProfile, number> = {
  none: 0,
  minimal: 1,
  runtime: 2,
  full: 3,
};

/** Construit la clé complète d'une directive pour un préfixe donné. */
export function directiveKey(
  short: string,
  prefix: string = DEFAULT_DIRECTIVE_PREFIX,
): string {
  // Cas particulier hérité v1 : le marqueur des scripts scopés est
  // "data-<prefix>-script-for" (attribut data-* valide sur <script>).
  if (short === "script-for") return `data-${prefix}-script-for`;
  // Directives runtime réservées : "<prefix>-bind", etc. (pas de "tag-").
  if (RUNTIME_SHORTS.has(short)) return `${prefix}-${short}`;
  return `${prefix}-tag-${short}`;
}

const RUNTIME_SHORTS = new Set([
  "bind",
  "repeat",
  "show",
  "action",
  "class",
  "model",
  "on",
]);

function spec(
  short: string,
  mode: DirectiveSpec["mode"],
  scope: DirectiveSpec["scope"],
  category: DirectiveSpec["category"],
  emitFrom: EmitProfile,
  description: string,
  reserved = false,
): DirectiveSpec {
  return {
    short,
    key: directiveKey(short),
    mode,
    scope,
    category,
    emitFrom,
    reserved,
    description,
  };
}

