/** Index par suffixe court. */
export const DIRECTIVES_BY_SHORT: ReadonlyMap<string, DirectiveSpec> = new Map(
  DIRECTIVE_REGISTRY.map((s) => [s.short, s]),
);

/** Index par clé complète (préfixe par défaut). */
export const DIRECTIVES_BY_KEY: ReadonlyMap<string, DirectiveSpec> = new Map(
  DIRECTIVE_REGISTRY.map((s) => [s.key, s]),
);

/** Suffixes des directives dérivées (jamais éditables). */
export const DERIVED_SHORTS: ReadonlySet<string> = new Set(
  DIRECTIVE_REGISTRY.filter((s) => s.mode === "derived").map((s) => s.short),
);

/** Une directive est-elle émise pour ce profil ? */
export function emittedInProfile(
  specItem: DirectiveSpec,
  profile: EmitProfile,
): boolean {
  if (profile === "none") return false;
  if (specItem.reserved) {
    // Les réservées ne sont émises que si une valeur non vide est posée.
    return PROFILE_ORDER[profile] >= PROFILE_ORDER[specItem.emitFrom];
  }
  return PROFILE_ORDER[profile] >= PROFILE_ORDER[specItem.emitFrom];
}

/**
 * Reconnaît une clé de directive pour un préfixe donné.
 * Retourne la spec si connue, sinon null (les clés inconnues au format
 * "<prefix>-…" sont conservées telles quelles à l'import : forward-compat).
 */
export function specForKey(
  key: string,
  prefix: string = DEFAULT_DIRECTIVE_PREFIX,
): DirectiveSpec | null {
  for (const s of DIRECTIVE_REGISTRY) {
    if (directiveKey(s.short, prefix) === key) return s;
  }
  return null;
}

/** Une clé appartient-elle à l'espace de noms Typos pour ce préfixe ? */
export function isTyposDirectiveKey(
  key: string,
  prefix: string = DEFAULT_DIRECTIVE_PREFIX,
): boolean {
  return (
    key.startsWith(`${prefix}-`) || key === `data-${prefix}-script-for`
  );
}
