import type {
  DeriveContext,
  DirectiveBag,
  TyposElement,
} from "./types.js";
import { DEFAULT_DIRECTIVE_PREFIX, DERIVED_SHORTS, directiveKey } from "./registry.js";
import { elementKind } from "./element.js";
import { cyrb53 } from "./hash.js";

/**
 * Recalcule TOUTES les directives dérivées de l'arbre, en un seul passage.
 * Pur et immuable : retourne un nouvel arbre, l'entrée n'est jamais mutée.
 *
 * Sémantique des frontières de composant (héritée v1, précisée v2) :
 * - component-first-parent = id de la racine de composant la plus proche,
 *   *soi inclus* (une racine appartient à sa propre frontière) ;
 * - component-path = adresse relative à cette frontière : "" hors composant
 *   et sur la racine de composant elle-même, puis "0", "0-1"… pour ses
 *   descendants.
 */
export function recomputeDerivedDirectives(
  root: TyposElement,
  ctx: DeriveContext,
): TyposElement {
  const prefix = ctx.directivePrefix ?? DEFAULT_DIRECTIVE_PREFIX;
  const k = (short: string): string => directiveKey(short, prefix);

  const visit = (
    el: TyposElement,
    parent: TyposElement | null,
    index: number,
    path: string,
    depth: number,
    prevId: string,
    nextId: string,
    boundaryId: string,
    boundaryPath: string,
  ): TyposElement => {
    const isRoot = el.isComponentRoot;
    const myBoundaryId = isRoot ? el.id : boundaryId;
    // Adresse relative à la frontière : "" sur la racine de composant,
    // sinon chemin depuis elle.
    const myBoundaryPath = isRoot
      ? ""
      : myBoundaryId === ""
        ? ""
        : boundaryPath;

    const children = el.children.map((child, i) =>
      visit(
        child,
        el,
        i,
        `${path}-${i}`,
        depth + 1,
        i > 0 ? (el.children[i - 1]?.id ?? "") : "",
        i < el.children.length - 1 ? (el.children[i + 1]?.id ?? "") : "",
        myBoundaryId,
        myBoundaryId === ""
          ? ""
          : myBoundaryPath === ""
            ? String(i)
            : `${myBoundaryPath}-${i}`,
      ),
    );

    const derived: DirectiveBag = {
      [k("type")]: el.type,
      [k("kind")]: elementKind(el),
      [k("path")]: path,
      [k("depth")]: depth,
      [k("index")]: index,
      [k("parent-id")]: parent?.id ?? "",
      [k("parent-type")]: parent?.type ?? "",
      [k("prev-id")]: prevId,
      [k("next-id")]: nextId,
      [k("child-count")]: children.length,
      [k("root-id")]: rootId,
      [k("component-first-parent")]: myBoundaryId,
      [k("component-path")]: isRoot ? "" : myBoundaryId === "" ? "" : boundaryPath,
      [k("template-id")]: ctx.templateId,
      [k("document-id")]: ctx.documentId,
      [k("target")]: ctx.target,
    };

    return { ...el, directives: { ...el.directives, ...derived }, children };
  };

  const rootId = root.id;
  return visit(root, null, 0, "0", 0, "", "", "", "");
}

/**
 * Calcule le hash Merkle de chaque élément (directive "hash").
 * Le hash reflète le CONTENU (type, attrs, classes, styles, css, innerHtml
 * si feuille, script, componentRef, slot, name) + les hashs des enfants.
 * Il exclut le volatil (horodatage, revision, topologie) : deux sous-arbres
 * au même contenu ont le même hash, où qu'ils soient.
 *
 * Séparé du recalcul dérivé (O(n) complet) pour rester optionnel : on
 * l'appelle à la sérialisation, au diff, ou explicitement.
 */
export function computeHashes(
  root: TyposElement,
  prefix: string = DEFAULT_DIRECTIVE_PREFIX,
): TyposElement {
  const hashKey = directiveKey("hash", prefix);
  const nameKey = directiveKey("name", prefix);
  const slotKey = directiveKey("slot", prefix);

  const visit = (el: TyposElement): TyposElement => {
    const children = el.children.map(visit);
    const basis = JSON.stringify([
      el.type,
      el.directives[nameKey] ?? "",
      el.directives[slotKey] ?? "",
      sortedEntries(el.attrs),
      el.classes,
      sortedEntries(el.styleOptions),
      el.customCss,
      children.length === 0 ? el.innerHtml : "",
      el.script,
      el.componentRef,
      el.isComponentRoot,
      children.map((c) => c.directives[hashKey] ?? ""),
    ]);
    return {
      ...el,
      children,
      directives: { ...el.directives, [hashKey]: cyrb53(basis) },
    };
  };
  return visit(root);
}

function sortedEntries(obj: Record<string, string>): [string, string][] {
  return Object.entries(obj).sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0));
}

/** Filtre un sac de directives : ne garde que les déclarées (patchs utilisateur). */
export function stripDerived(
  bag: DirectiveBag,
  prefix: string = DEFAULT_DIRECTIVE_PREFIX,
): DirectiveBag {
  const out: DirectiveBag = {};
  for (const [key, value] of Object.entries(bag)) {
    let derived = false;
    for (const short of DERIVED_SHORTS) {
      if (directiveKey(short, prefix) === key) {
        derived = true;
        break;
      }
    }
    if (!derived) out[key] = value;
  }
  return out;
}
