import type {
  DeriveContext,
  DirectiveBag,
  DocumentKind,
  EmitProfile,
  TemplateTarget,
  TyposDocument,
  TyposElement,
  TyposTemplate,
} from "./types.js";
import { createDocumentId, createElementId, createTemplateId } from "./ids.js";
import { DEFAULT_DIRECTIVE_PREFIX } from "./registry.js";
import { computeHashes, recomputeDerivedDirectives } from "./directives.js";
import { createElement } from "./element.js";
import { cyrb53 } from "./hash.js";
import { validateDocument } from "./validate.js";

/**
 * Sérialisation parfaite = trois garanties :
 *
 * 1. CANONIQUE  — ordre de clés fixe, schéma-dirigé : le même document
 *    produit toujours exactement les mêmes octets. Diff, hash et
 *    versionnage deviennent triviaux.
 * 2. RÉVERSIBLE — serialize(parse(s)) === s, et parse(serialize(doc))
 *    restitue le document à l'identique.
 * 3. MIGRABLE   — tout format antérieur (v1 React) est reconnu et
 *    converti sans perte vers le format courant.
 */

/* ------------------------------------------------------------------ */
/* Ordres canoniques de clés (schéma-dirigés)                          */
/* ------------------------------------------------------------------ */

const DOCUMENT_KEY_ORDER = [
  "format", "formatVersion", "id", "kind", "name",
  "createdAt", "updatedAt", "settings", "templates",
  "activeTemplateId", "meta",
] as const;

const SETTINGS_KEY_ORDER = ["directivePrefix", "emitProfile"] as const;

const TEMPLATE_KEY_ORDER = ["id", "name", "target", "isMain", "tree"] as const;

const ELEMENT_KEY_ORDER = [
  "id", "type", "isComponentRoot", "componentRef", "directives",
  "attrs", "styleOptions", "customCss", "classes", "innerHtml",
  "script", "children", "meta",
] as const;

const COMPONENT_REF_KEY_ORDER = ["type", "name", "componentId"] as const;

/* ------------------------------------------------------------------ */
/* Création                                                            */
/* ------------------------------------------------------------------ */

export interface CreateDocumentOptions {
  kind?: DocumentKind;
  name?: string;
  id?: string;
  directivePrefix?: string;
  emitProfile?: EmitProfile;
  target?: TemplateTarget;
  /** Arbre racine initial (une div "root" par défaut). */
  rootTree?: TyposElement;
  now?: () => string;
}

/** Fabrique un document neuf avec un template initial, dérivées à jour. */
export function createDocument(
  options: CreateDocumentOptions = {},
): TyposDocument {
  const now = options.now ? options.now() : new Date().toISOString();
  const id = options.id ?? createDocumentId();
  const prefix = options.directivePrefix ?? DEFAULT_DIRECTIVE_PREFIX;
  const target = options.target ?? "web";
  const templateId = createTemplateId();

  const tree =
    options.rootTree ??
    createElement("div", {
      name: "root",
      origin: "template",
      directivePrefix: prefix,
      now: options.now,
    });

  const ctx: DeriveContext = {
    documentId: id,
    templateId,
    target,
    directivePrefix: prefix,
  };

  return {
    format: "typos-document",
    formatVersion: 2,
    id,
    kind: options.kind ?? "page",
    name: options.name ?? "Sans titre",
    createdAt: now,
    updatedAt: now,
    settings: {
      directivePrefix: prefix,
      emitProfile: options.emitProfile ?? "runtime",
    },
    templates: [
      {
        id: templateId,
        name: options.kind === "component" ? "main" : "Template 1",
        target,
        ...(options.kind === "component" ? { isMain: true } : {}),
        tree: recomputeDerivedDirectives(tree, ctx),
      },
    ],
    activeTemplateId: templateId,
    meta: {},
  };
}

/* ------------------------------------------------------------------ */
/* Sérialisation canonique                                             */
/* ------------------------------------------------------------------ */

type Json = string | number | boolean | null | Json[] | { [k: string]: Json };

function orderKeys(
  value: Record<string, unknown>,
  order: readonly string[],
): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const key of order) {
    if (key in value && value[key] !== undefined) out[key] = value[key];
  }
  // Clés hors schéma (extensions futures) : à la fin, triées.
  const extra = Object.keys(value)
    .filter((k) => !order.includes(k) && value[k] !== undefined)
    .sort();
  for (const key of extra) out[key] = value[key];
  return out;
}

/** Objets libres (directives, attrs, styleOptions, meta) : clés triées. */
function sortKeys(value: Record<string, unknown>): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const key of Object.keys(value).sort()) out[key] = value[key];
  return out;
}

function canonicalElement(el: TyposElement): Record<string, unknown> {
  return orderKeys(
    {
      ...el,
      componentRef: el.componentRef
        ? orderKeys(el.componentRef as unknown as Record<string, unknown>, COMPONENT_REF_KEY_ORDER)
        : null,
      directives: sortKeys(el.directives),
      attrs: sortKeys(el.attrs),
      styleOptions: sortKeys(el.styleOptions),
      meta: sortKeys(el.meta),
      children: el.children.map(canonicalElement),
    },
    ELEMENT_KEY_ORDER,
  );
}

function canonicalDocument(doc: TyposDocument): Record<string, unknown> {
  return orderKeys(
    {
      ...doc,
      settings: orderKeys(
        doc.settings as unknown as Record<string, unknown>,
        SETTINGS_KEY_ORDER,
      ),
      templates: doc.templates.map((t) =>
        orderKeys(
          { ...t, tree: canonicalElement(t.tree) },
          TEMPLATE_KEY_ORDER,
        ),
      ),
      meta: sortKeys(doc.meta),
    },
    DOCUMENT_KEY_ORDER,
  );
}

export interface SerializeOptions {
  /** Poser les hashs Merkle avant sérialisation (défaut : true). */
  withHashes?: boolean;
  /** Indentation JSON (défaut : 2 ; 0 = compact). */
  space?: number;
}

/** Document → JSON canonique (déterministe à l'octet près). */
export function serializeDocument(
  doc: TyposDocument,
  options: SerializeOptions = {},
): string {
  const withHashes = options.withHashes ?? true;
  const prepared: TyposDocument = withHashes
    ? {
        ...doc,
        templates: doc.templates.map((t) => ({
          ...t,
          tree: computeHashes(t.tree, doc.settings.directivePrefix),
        })),
      }
    : doc;
  return JSON.stringify(
    canonicalDocument(prepared) as Json,
    null,
    options.space ?? 2,
  );
}

/**
 * Hash global du document — calculé sur la forme canonique SANS les
 * champs volatils (updatedAt). Deux documents au même contenu ont le
 * même hash quel que soit le moment de la sauvegarde.
 */
export function documentHash(doc: TyposDocument): string {
  const canonical = canonicalDocument({
    ...doc,
    updatedAt: "",
  });
  return cyrb53(JSON.stringify(canonical));
}

/* ------------------------------------------------------------------ */
/* Parsing + migration                                                 */
/* ------------------------------------------------------------------ */

export interface ParseDocumentResult {
  document: TyposDocument;
  /** true si une migration a été appliquée. */
  migrated: boolean;
}

/**
 * Parse un JSON de document. Reconnaît :
 * - le format v2 courant ("typos-document") ;
 * - le format projet v1 (React) : { templates[], activeTemplateId, … } ;
 * - un arbre d'élément nu (v1 export brut).
 * Valide, recalcule les dérivées, lève une Error explicite si invalide.
 */
export function parseDocument(json: string): ParseDocumentResult {
  let raw: unknown;
  try {
    raw = JSON.parse(json);
  } catch (e) {
    throw new Error(
      `Typos: JSON invalide — ${(e as Error).message}`,
    );
  }
  return parseDocumentValue(raw);
}

export function parseDocumentValue(raw: unknown): ParseDocumentResult {
  if (!raw || typeof raw !== "object") {
    throw new Error("Typos: document invalide (objet attendu).");
  }
  const obj = raw as Record<string, unknown>;

  let doc: TyposDocument;
  let migrated = false;

  if (obj["format"] === "typos-document") {
    doc = obj as unknown as TyposDocument;
  } else {
    doc = migrateLegacy(obj);
    migrated = true;
  }

  // Recalcul systématique des dérivées : on ne fait jamais confiance
  // aux dérivées stockées, le noyau reste seul maître.
  const prefix = doc.settings.directivePrefix;
  doc = {
    ...doc,
    templates: doc.templates.map((t) => ({
      ...t,
      tree: recomputeDerivedDirectives(t.tree, {
        documentId: doc.id,
        templateId: t.id,
        target: t.target,
        directivePrefix: prefix,
      }),
    })),
  };

  const result = validateDocument(doc);
  if (!result.ok) {
    const first = result.issues.find((i) => i.level === "error");
    throw new Error(
      `Typos: document invalide — ${first?.message ?? "erreur inconnue"} (${first?.path ?? "?"})`,
    );
  }

  return { document: doc, migrated };
}

/* ------------------------------------------------------------------ */
/* Migration v1 → v2                                                   */
/* ------------------------------------------------------------------ */

interface LegacyElement {
  id?: string;
  type?: string;
  isComponentRoot?: boolean;
  componentRef?: { type?: string; name?: string; componentId?: string } | null;
  directives?: Record<string, unknown>;
  styleOptions?: Record<string, string>;
  customCss?: string;
  classes?: string[];
  innerHtml?: string;
  script?: string;
  children?: LegacyElement[];
}

function migrateElement(legacy: LegacyElement, now: string): TyposElement {
  const id = typeof legacy.id === "string" && legacy.id ? legacy.id : createElementId();
  const directives: DirectiveBag = {};
  for (const [key, value] of Object.entries(legacy.directives ?? {})) {
    if (
      typeof value === "string" ||
      typeof value === "number" ||
      typeof value === "boolean" ||
      value === null
    ) {
      // Normalisation v1 : les clés "tag-component-*" (sans préfixe en v1)
      // deviennent "tekton-tag-component-*".
      const normalized = key.startsWith("tag-component-")
        ? `tekton-${key}`
        : key;
      directives[normalized] = value;
    }
  }

  const base = createElement(legacy.type ?? "div", {
    id,
    origin: "migration",
    isComponentRoot: legacy.isComponentRoot ?? false,
    componentRef:
      legacy.componentRef &&
      typeof legacy.componentRef.componentId === "string"
        ? {
            type: legacy.componentRef.type ?? "",
            name: legacy.componentRef.name ?? "",
            componentId: legacy.componentRef.componentId,
          }
        : null,
    styleOptions: legacy.styleOptions ?? {},
    customCss: legacy.customCss ?? "",
    classes: legacy.classes ?? [],
    innerHtml: legacy.innerHtml ?? "",
    script: legacy.script ?? "",
    now: () => now,
  });

  return {
    ...base,
    // Les directives héritées (déclarées) écrasent les valeurs par défaut ;
    // les dérivées seront de toute façon recalculées derrière.
    directives: { ...base.directives, ...directives, "tekton-tag-id": id },
    children: (legacy.children ?? []).map((c) => migrateElement(c, now)),
  };
}

function migrateLegacy(obj: Record<string, unknown>): TyposDocument {
  const now = new Date().toISOString();

  // Cas 1 : arbre d'élément nu (a un "type" et des "children").
  if (typeof obj["type"] === "string" && Array.isArray(obj["children"])) {
    const tree = migrateElement(obj as LegacyElement, now);
    const base = createDocument({ name: "Import v1", rootTree: tree, now: () => now });
    return base;
  }

  // Cas 2 : projet v1 { templates: [...], activeTemplateId, name?, kind?/mode? }.
  if (Array.isArray(obj["templates"])) {
    const id = typeof obj["id"] === "string" ? obj["id"] : createDocumentId();
    const kindRaw = obj["kind"] ?? obj["mode"];
    const kind: DocumentKind = kindRaw === "component" ? "component" : "page";
    const legacyTemplates = obj["templates"] as Array<Record<string, unknown>>;

    const templates: TyposTemplate[] = legacyTemplates.map((t, i) => {
      const treeRaw = (t["tree"] ?? t["root"] ?? t["element"]) as
        | LegacyElement
        | undefined;
      const target = t["target"];
      return {
        id: typeof t["id"] === "string" ? (t["id"] as string) : createTemplateId(),
        name: typeof t["name"] === "string" ? (t["name"] as string) : `Template ${i + 1}`,
        target:
          target === "mobile" || target === "tablet" || target === "web"
            ? target
            : "web",
        tree: treeRaw
          ? migrateElement(treeRaw, now)
          : createElement("div", { name: "root", origin: "migration", now: () => now }),
      };
    });

    if (templates.length === 0) {
      templates.push({
        id: createTemplateId(),
        name: "Template 1",
        target: "web",
        tree: createElement("div", { name: "root", origin: "migration", now: () => now }),
      });
    }

    const active = obj["activeTemplateId"];
    const activeTemplateId =
      typeof active === "string" && templates.some((t) => t.id === active)
        ? active
        : (templates[0] as TyposTemplate).id;

    return {
      format: "typos-document",
      formatVersion: 2,
      id,
      kind,
      name: typeof obj["name"] === "string" ? (obj["name"] as string) : "Import v1",
      createdAt:
        typeof obj["createdAt"] === "string" ? (obj["createdAt"] as string) : now,
      updatedAt: now,
      settings: {
        directivePrefix: DEFAULT_DIRECTIVE_PREFIX,
        emitProfile: "runtime",
      },
      templates,
      activeTemplateId,
      meta: {},
    };
  }

  throw new Error(
    "Typos: format non reconnu (ni typos-document v2, ni projet v1, ni arbre d'élément).",
  );
}
