import type {
  EngineEventMap,
  EngineListener,
  EngineWildcardListener,
} from "../core/types.js";

/**
 * Émetteur d'événements typé, minuscule et sans dépendance.
 * Invariant moteur : UN SEUL flux d'événements — tout ce qui arrive
 * dans le moteur passe par ici, l'UI ne fait que s'y abonner.
 */
export class Emitter {
  private listeners = new Map<string, Set<(payload: unknown, name: string) => void>>();

  on<K extends keyof EngineEventMap>(name: K, fn: EngineListener<K>): () => void;
  on(name: "*", fn: EngineWildcardListener): () => void;
  on(name: string, fn: (payload: never, name: never) => void): () => void {
    let set = this.listeners.get(name);
    if (!set) {
      set = new Set();
      this.listeners.set(name, set);
    }
    set.add(fn as (payload: unknown, name: string) => void);
    return () => this.off(name as "*", fn as EngineWildcardListener);
  }

  off(name: string, fn: (payload: never, name: never) => void): void {
    this.listeners.get(name)?.delete(fn as (payload: unknown, name: string) => void);
  }

  emit<K extends keyof EngineEventMap>(name: K, payload: EngineEventMap[K]): void {
    for (const fn of this.listeners.get(name) ?? []) fn(payload, name);
    for (const fn of this.listeners.get("*") ?? []) fn(payload, name);
  }

  clear(): void {
    this.listeners.clear();
  }
}
