import type {
  ComponentRef,
  DirectiveBag,
  DirectiveValue,
  ElementKind,
  ElementOrigin,
  TyposElement,
} from "./types.js";
import { createElementId } from "./ids.js";
import { DEFAULT_DIRECTIVE_PREFIX, directiveKey } from "./registry.js";

/** Balises HTML void : fermées automatiquement, jamais d'enfants ni d'innerHtml. */
export const VOID_TAGS: ReadonlySet<string> = new Set([
  "area", "base", "br", "col", "embed", "hr", "img", "input",
  "link", "meta", "param", "source", "track", "wbr",
]);

export interface CreateElementOptions {
  id?: string;
  name?: string;
  origin?: ElementOrigin;
  isComponentRoot?: boolean;
  componentRef?: ComponentRef | null;
  attrs?: Record<string, string>;
  styleOptions?: Record<string, string>;
  customCss?: string;
  classes?: string[];
  innerHtml?: string;
  script?: string;
  children?: TyposElement[];
  meta?: Record<string, unknown>;
  directives?: DirectiveBag;
  directivePrefix?: string;
  /** Horloge injectable (tests). */
  now?: () => string;
}

/**
 * Fabrique un élément neuf, traçage complet posé dès la naissance.
 * Les directives dérivées seront complétées par recomputeDerivedDirectives().
 */
export function createElement(
  type: string,
  options: CreateElementOptions = {},
): TyposElement {
  const prefix = options.directivePrefix ?? DEFAULT_DIRECTIVE_PREFIX;
  const now = options.now ? options.now() : new Date().toISOString();
  const id = options.id ?? createElementId();
  const k = (short: string): string => directiveKey(short, prefix);

  const directives: DirectiveBag = {
    [k("id")]: id,
    [k("name")]: options.name ?? type,
    [k("origin")]: options.origin ?? "api",
    [k("source-id")]: "",
    [k("created-at")]: now,
    [k("updated-at")]: now,
    [k("revision")]: 0,
    [k("locked")]: false,
    [k("hidden")]: false,
    [k("slot")]: "",
    ...(options.isComponentRoot
      ? {
          [k("component-type")]: options.componentRef?.type ?? "",
          [k("component-name")]:
            options.componentRef?.name ?? options.name ?? type,
          [k("component-id")]: options.componentRef?.componentId ?? "",
          [k("component-version")]: "",
        }
      : {}),
    ...(options.directives ?? {}),
  };

  return {
    id,
    type,
    isComponentRoot: options.isComponentRoot ?? false,
    componentRef: options.componentRef ?? null,
    directives,
    attrs: { ...(options.attrs ?? {}) },
    styleOptions: { ...(options.styleOptions ?? {}) },
    customCss: options.customCss ?? "",
    classes: [...(options.classes ?? [])],
    innerHtml: options.innerHtml ?? "",
    script: options.script ?? "",
    children: options.children ?? [],
    meta: { ...(options.meta ?? {}) },
  };
}

/** Nature effective d'un élément. */
export function elementKind(el: TyposElement): ElementKind {
  if (el.isComponentRoot) return "component-root";
  if (el.componentRef) return "component-instance";
  return "element";
}

/** Lit une directive par suffixe court (préfixe configurable). */
export function getDirective(
  el: TyposElement,
  short: string,
  prefix: string = DEFAULT_DIRECTIVE_PREFIX,
): DirectiveValue | undefined {
  return el.directives[directiveKey(short, prefix)];
}

/**
 * Pose une directive *déclarée* (retourne un nouvel élément — immuable).
 * Refuse silencieusement d'écrire une dérivée : elles appartiennent au noyau.
 */
export function withDirective(
  el: TyposElement,
  short: string,
  value: DirectiveValue,
  prefix: string = DEFAULT_DIRECTIVE_PREFIX,
): TyposElement {
  return {
    ...el,
    directives: { ...el.directives, [directiveKey(short, prefix)]: value },
  };
}
