import type {
  DirectiveBag,
  ElementPatch,
  TyposElement,
} from "./types.js";
import { createElementId } from "./ids.js";
import { DEFAULT_DIRECTIVE_PREFIX, directiveKey } from "./registry.js";
import { stripDerived } from "./directives.js";
import { VOID_TAGS } from "./element.js";

/**
 * Opérations d'arbre : toutes PURES et IMMUABLES.
 * Aucune ne mute son entrée ; toutes retournent un nouvel arbre avec
 * partage structurel (les branches non touchées sont réutilisées telles
 * quelles — l'historique undo/redo s'appuie dessus).
 */

/* ------------------------------------------------------------------ */
/* Lecture                                                             */
/* ------------------------------------------------------------------ */

export function findById(
  root: TyposElement,
  id: string,
): TyposElement | null {
  if (root.id === id) return root;
  for (const child of root.children) {
    const found = findById(child, id);
    if (found) return found;
  }
  return null;
}

/** Résout une adresse "0-1-2" (racine = "0"). */
export function findByPath(
  root: TyposElement,
  path: string,
): TyposElement | null {
  const parts = path.split("-").map(Number);
  if (parts[0] !== 0) return null;
  let node: TyposElement = root;
  for (let i = 1; i < parts.length; i++) {
    const idx = parts[i];
    if (idx === undefined || Number.isNaN(idx)) return null;
    const next = node.children[idx];
    if (!next) return null;
    node = next;
  }
  return node;
}

export function getParent(
  root: TyposElement,
  id: string,
): TyposElement | null {
  if (root.id === id) return null;
  for (const child of root.children) {
    if (child.id === id) return root;
    const found = getParent(child, id);
    if (found) return found;
  }
  return null;
}

/** Chaîne d'ancêtres, de la racine (incluse) au parent direct. */
export function ancestorsOf(
  root: TyposElement,
  id: string,
): TyposElement[] {
  const chain: TyposElement[] = [];
  const walk = (node: TyposElement): boolean => {
    if (node.id === id) return true;
    for (const child of node.children) {
      if (walk(child)) {
        chain.unshift(node);
        return true;
      }
    }
    return false;
  };
  walk(root);
  return chain;
}

/** `maybeAncestorId` est-il un ancêtre (strict) de `id` ? */
export function isAncestor(
  root: TyposElement,
  maybeAncestorId: string,
  id: string,
): boolean {
  return ancestorsOf(root, id).some((a) => a.id === maybeAncestorId);
}

/** Parcours préfixe complet. */
export function walk(
  root: TyposElement,
  visit: (el: TyposElement, parent: TyposElement | null, depth: number) => void,
): void {
  const rec = (
    el: TyposElement,
    parent: TyposElement | null,
    depth: number,
  ): void => {
    visit(el, parent, depth);
    for (const child of el.children) rec(child, el, depth + 1);
  };
  rec(root, null, 0);
}

/** Aplatit l'arbre en liste (ordre préfixe). */
export function flatten(root: TyposElement): TyposElement[] {
  const out: TyposElement[] = [];
  walk(root, (el) => out.push(el));
  return out;
}

/** Compte les éléments. */
export function countElements(root: TyposElement): number {
  let n = 0;
  walk(root, () => n++);
  return n;
}

/* ------------------------------------------------------------------ */
/* Écriture (immuable, partage structurel)                             */
/* ------------------------------------------------------------------ */

/**
 * Remplace le sous-arbre dont la racine a l'id donné.
 * Brique interne de toutes les mutations. Retourne l'arbre d'origine
 * si l'id est introuvable (référence identique = aucun changement).
 */
export function replaceById(
  root: TyposElement,
  id: string,
  replacer: (el: TyposElement) => TyposElement,
): TyposElement {
  if (root.id === id) return replacer(root);
  let changed = false;
  const children = root.children.map((child) => {
    const next = replaceById(child, id, replacer);
    if (next !== child) changed = true;
    return next;
  });
  return changed ? { ...root, children } : root;
}

export interface InsertResult {
  root: TyposElement;
  inserted: TyposElement;
}

/**
 * Insère `element` comme enfant de `parentId` à `index`
 * (fin si index absent ou hors bornes). Refuse d'insérer dans une
 * balise void (l'arbre d'origine est retourné inchangé).
 */
export function insertAt(
  root: TyposElement,
  parentId: string,
  element: TyposElement,
  index?: number,
): InsertResult {
  const parent = findById(root, parentId);
  if (!parent || VOID_TAGS.has(parent.type)) {
    return { root, inserted: element };
  }
  const next = replaceById(root, parentId, (p) => {
    const children = [...p.children];
    const at =
      index === undefined || index < 0 || index > children.length
        ? children.length
        : index;
    children.splice(at, 0, element);
    return { ...p, children };
  });
  return { root: next, inserted: element };
}

/** Retire l'élément (interdit sur la racine — retourne l'arbre inchangé). */
export function removeById(root: TyposElement, id: string): TyposElement {
  if (root.id === id) return root;
  const parent = getParent(root, id);
  if (!parent) return root;
  return replaceById(root, parent.id, (p) => ({
    ...p,
    children: p.children.filter((c) => c.id !== id),
  }));
}

/**
 * Déplace `id` sous `newParentId` à `index`.
 * Refus (arbre inchangé) si : élément ou parent introuvable, déplacement
 * dans soi-même ou un de ses descendants, parent void, ou id = racine.
 */
export function moveTo(
  root: TyposElement,
  id: string,
  newParentId: string,
  index?: number,
): TyposElement {
  if (id === root.id || id === newParentId) return root;
  const el = findById(root, id);
  const target = findById(root, newParentId);
  if (!el || !target || VOID_TAGS.has(target.type)) return root;
  if (isAncestor(root, id, newParentId)) return root; // dans son propre sous-arbre

  const without = removeById(root, id);
  if (without === root) return root;
  return insertAt(without, newParentId, el, index).root;
}

/** Réordonne un élément parmi ses frères. */
export function reorder(
  root: TyposElement,
  id: string,
  newIndex: number,
): TyposElement {
  const parent = getParent(root, id);
  if (!parent) return root;
  return replaceById(root, parent.id, (p) => {
    const from = p.children.findIndex((c) => c.id === id);
    if (from === -1) return p;
    const children = [...p.children];
    const moved = children.splice(from, 1)[0];
    if (!moved) return p;
    const to = Math.max(0, Math.min(newIndex, children.length));
    children.splice(to, 0, moved);
    return { ...p, children };
  });
}

/**
 * Applique un patch partiel à un élément.
 * Les directives dérivées présentes dans `patch.directives` sont
 * ignorées (elles appartiennent au noyau) ; `revision` est incrémentée
 * et `updated-at` reposée.
 */
export function updateElement(
  root: TyposElement,
  id: string,
  patch: ElementPatch,
  prefix: string = DEFAULT_DIRECTIVE_PREFIX,
  now: () => string = () => new Date().toISOString(),
): TyposElement {
  return replaceById(root, id, (el) => {
    const declared: DirectiveBag = patch.directives
      ? stripDerived(patch.directives, prefix)
      : {};
    const revKey = directiveKey("revision", prefix);
    const updKey = directiveKey("updated-at", prefix);
    const currentRev = el.directives[revKey];
    const rev = typeof currentRev === "number" ? currentRev + 1 : 1;
    const { directives: _ignored, ...rest } = patch;
    return {
      ...el,
      ...rest,
      attrs: patch.attrs ? { ...patch.attrs } : el.attrs,
      styleOptions: patch.styleOptions
        ? { ...patch.styleOptions }
        : el.styleOptions,
      classes: patch.classes ? [...patch.classes] : el.classes,
      meta: patch.meta ? { ...patch.meta } : el.meta,
      directives: {
        ...el.directives,
        ...declared,
        [revKey]: rev,
        [updKey]: now(),
      },
    };
  });
}

export interface CloneResult {
  root: TyposElement;
  clone: TyposElement;
}

/**
 * Clone profond d'un sous-arbre : nouveaux ids partout, origin="clone",
 * source-id = id d'origine, revision remise à 0. Le clone est inséré
 * juste après l'original (même parent).
 */
export function cloneSubtree(
  root: TyposElement,
  id: string,
  prefix: string = DEFAULT_DIRECTIVE_PREFIX,
  now: () => string = () => new Date().toISOString(),
): CloneResult {
  const source = findById(root, id);
  const parent = getParent(root, id);
  if (!source || !parent) return { root, clone: root };

  const stamp = now();
  const k = (short: string): string => directiveKey(short, prefix);

  const deepClone = (el: TyposElement): TyposElement => {
    const newId = createElementId();
    return {
      ...el,
      id: newId,
      attrs: { ...el.attrs },
      styleOptions: { ...el.styleOptions },
      classes: [...el.classes],
      meta: { ...el.meta },
      componentRef: el.componentRef ? { ...el.componentRef } : null,
      directives: {
        ...el.directives,
        [k("id")]: newId,
        [k("origin")]: "clone",
        [k("source-id")]: el.id,
        [k("created-at")]: stamp,
        [k("updated-at")]: stamp,
        [k("revision")]: 0,
      },
      children: el.children.map(deepClone),
    };
  };

  const clone = deepClone(source);
  const at = parent.children.findIndex((c) => c.id === id) + 1;
  const next = insertAt(root, parent.id, clone, at).root;
  return { root: next, clone };
}

/**
 * Enveloppe un élément dans un nouveau parent (ex. wrap dans une div).
 * Le wrapper prend la place de l'élément, qui devient son unique enfant.
 * Interdit sur la racine.
 */
export function wrapElement(
  root: TyposElement,
  id: string,
  wrapper: TyposElement,
): TyposElement {
  if (root.id === id || VOID_TAGS.has(wrapper.type)) return root;
  const parent = getParent(root, id);
  if (!parent) return root;
  return replaceById(root, parent.id, (p) => ({
    ...p,
    children: p.children.map((c) =>
      c.id === id ? { ...wrapper, children: [c] } : c,
    ),
  }));
}

/**
 * Dissout un élément : ses enfants remontent à sa place chez son parent.
 * Interdit sur la racine.
 */
export function unwrapElement(root: TyposElement, id: string): TyposElement {
  if (root.id === id) return root;
  const parent = getParent(root, id);
  if (!parent) return root;
  return replaceById(root, parent.id, (p) => {
    const children: TyposElement[] = [];
    for (const c of p.children) {
      if (c.id === id) children.push(...c.children);
      else children.push(c);
    }
    return { ...p, children };
  });
}
